#include <iostream>
#include <vector>

using namespace std;

namespace NumberTheory {
    const long long MOD = 998;

    struct Mod998 {
        long long add(long long a, long long b) {
            long long res = a + b;
            if (res >= MOD) res -= MOD;
            return res;
        }

        long long subtract(long long a, long long b) {
            long long res = a - b;
            if (res < 0) res += MOD;
            return res;
        }

        long long mult(long long a, long long b) {
            return (a * b) % MOD;
        }

        long long smallInv(long long a) {
            // Fermat's little theorem for modular inverse since MOD is prime
            return powMod(a, MOD - 2);
        }

        long long powMod(long long base, long long exp) {
            long long result = 1;
            long long cur = base % MOD;
            while (exp > 0) {
                if (exp & 1) result = (result * cur) % MOD;
                cur = (cur * cur) % MOD;
                exp >>= 1;
            }
            return result;
        }

        long long ncr(int n, int r) {
            if (r > n || r < 0) return 0;
            long long numerator = 1;
            long long denominator = 1;
            for (int i = 1; i <= r; ++i) {
                numerator = mult(numerator, n - i + 1);
                denominator = mult(denominator, i);
            }
            return mult(numerator, smallInv(denominator));
        }
    };
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    NumberTheory::Mod998 mod;

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; ++i) {
        long long denom = mod.smallInv(n + m - i);
        p = mod.mult(p, n - i);
        p = mod.mult(p, denom);
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; ++k) {
        long long numPhases = mod.mult(m + k, mod.smallInv(k));
        long long term = mod.mult(mod.ncr(n, k), numPhases);
        term = mod.mult(term, phaseSize);
        if ((k & 1) == 1)
            answer = mod.add(answer, term);
        else
            answer = mod.subtract(answer, term);
    }

    cout << answer << "\n";

    return 0;
}

